  1→/**
  2→ * Author confidence (P2-1).
  3→ *
  4→ * A prior for cold-start assets only: a freshly extracted asset has no record
  5→ * of its own, and the one thing known about it is who wrote it. Once an asset
  6→ * has its own outcomes, those always win — using the author score to judge an
  7→ * asset that already has evidence would be circular.
  8→ *
  9→ *   confidence = (V + α·μ) / (V + C + α)
 10→ *
 11→ *   V  cross_user `validated` events on the author's assets
 12→ *   C  cross_user `corrected` events with reason wrong / stale
 13→ *   μ  the mean validation rate of the OTHER authors who have outcomes
 14→ *      (leave-one-out), itself shrunk toward neutral 0.5 by how many
 15→ *      outcomes those authors have; exactly 0.5 when there are none
 16→ *   α  shrinkage strength, 5
 17→ *
 18→ * Why each of those:
 19→ *
 20→ *   - Only cross_user counts. An author validating their own asset is
 21→ *     self-certification; it says nothing a reviewer can rely on.
 22→ *   - No raw ratio. Two validations out of two reads as 100% with a raw ratio;
 23→ *     shrinkage pulls small samples toward the pool mean, and large volumes
 24→ *     with a poor rate do not climb just by being large.
 25→ *   - μ excludes the author being scored. With one author in the pool, the
 26→ *     "pool mean" would be that author's own rate, and the shrinkage would
 27→ *     shrink toward the very number it exists to temper: V=1, C=0 would give
 28→ *     exactly 1.0 again. Leave-one-out makes the prior an outside opinion, and
 29→ *     the neutral fallback is stated in the output so a reader can see when
 30→ *     it was used.
 31→ *   - Decoy assets are excluded. Their outcomes are planted truth for measuring
 32→ *     the corrected miss rate, not the author's work.
 33→ *   - Person and agent are scored separately. The two diverging (the same
 34→ *     person's assets reliable through one agent and not another) points at
 35→ *     an extraction path, not a person.
 36→ *   - Not computable ⇒ null, never 0. Zero is a claim; null is the absence of one.
 37→ *
 38→ * Not applied here: time decay. Every event in this evaluation falls inside
 39→ * one window, so a decay term would multiply everything by the same constant.
 40→ * The output carries the event span so a reader can see that for themselves.
 41→ *
 42→ * Usage:
 43→ *   node evaluation/gate/author-confidence.mjs <events.jsonl ...> [--decoys=FILE] [--json]
 44→ */
 45→
 46→import { readFileSync } from "node:fs";
 47→import { parseJsonl } from "../provenance/build-events.mjs";
 48→
 49→export const ALPHA = 5;
 50→export const NEUTRAL_PRIOR = 0.5;
 51→export const DOWNWEIGHT_REASONS = new Set(["wrong", "stale"]);
 52→
 53→const KEY = { user: "producer_user_id", agent: "producer_agent_id" };
 54→
 55→/** Does this event count toward any author's tally? */
 56→export function countsForAuthor(event, decoyIds) {
 57→  if (event.excluded_by_snapshot) return false;
 58→  if (decoyIds.has(event.asset_id)) return false;
 59→  if (event.relation !== "cross_user") return false;
 60→  if (event.state === "validated") return true;
 61→  if (event.state === "corrected") return DOWNWEIGHT_REASONS.has(event.corrected_reason);
 62→  return false;
 63→}
 64→
 65→/** Per-author raw tallies. `by` is "user" or "agent". */
 66→export function authorTallies(events, { by = "user", decoyIds = new Set() } = {}) {
 67→  const key = KEY[by];
 68→  if (!key) throw new Error(`by must be "user" or "agent", got ${by}`);
 69→  const tallies = new Map();
 70→  for (const e of events) {
 71→    if (!countsForAuthor(e, decoyIds)) continue;
 72→    const author = e[key] || "";
 73→    if (!author) continue;
 74→    if (!tallies.has(author)) {
 75→      tallies.set(author, { validated: 0, corrected: 0, consumers: new Set(), tasks: new Set(), assets: new Set(), first: null, last: null });
 76→    }
 77→    const t = tallies.get(author);
 78→    if (e.state === "validated") {
 79→      t.validated += 1;
 80→      if (e.actor_user_id) t.consumers.add(e.actor_user_id);
 81→      if (e.task_id) t.tasks.add(e.task_id);
 82→    } else {
 83→      t.corrected += 1;
 84→    }
 85→    t.assets.add(e.asset_id);
 86→    if (e.occurred_at) {
 87→      if (!t.first || e.occurred_at < t.first) t.first = e.occurred_at;
 88→      if (!t.last || e.occurred_at > t.last) t.last = e.occurred_at;
 89→    }
 90→  }
 91→  return tallies;
 92→}
 93→
 94→/** Mean validation rate over the authors with outcomes, excluding one. Null if none. */
 95→export function leaveOneOutMean(tallies, exclude) {
 96→  const rates = [];
 97→  for (const [author, t] of tallies) {
 98→    if (author === exclude) continue;
 99→    const n = t.validated + t.corrected;
100→    if (n > 0) rates.push(t.validated / n);
101→  }
102→  if (rates.length === 0) return null;
103→  return rates.reduce((a, b) => a + b, 0) / rates.length;
104→}
105→
106→function round(x) { return Math.round(x * 1000) / 1000; }
107→
108→/** Score one author. Always returns an object; `confidence` is null when not computable. */
109→export function authorConfidence(events, author, { by = "user", decoyIds = new Set(), alpha = ALPHA } = {}) {
110→  const tallies = authorTallies(events, { by, decoyIds });
111→  const t = tallies.get(author) ?? { validated: 0, corrected: 0, consumers: new Set(), tasks: new Set(), assets: new Set(), first: null, last: null };
112→  const n = t.validated + t.corrected;
113→  const base = {
114→    by, author,
115→    validated: t.validated, corrected: t.corrected,
116→    distinct_consumers: t.consumers.size,
117→    distinct_tasks: t.tasks.size,
118→    distinct_assets: t.assets.size,
119→    event_span: t.first ? { first: t.first, last: t.last } : null,
120→    shrinkage_alpha: alpha,
121→  };
122→  if (n === 0) {
123→    return { ...base, computable: false, confidence: null, raw_rate: null, prior: null, prior_source: "none: no cross-person outcomes for this author" };
124→  }
125→  const { mu, prior_source } = priorFor(tallies, author, alpha);
126→  return {
127→    ...base,
128→    computable: true,
129→    confidence: round((t.validated + alpha * mu) / (n + alpha)),
130→    raw_rate: round(t.validated / n),
131→    prior: round(mu),
132→    prior_source,
133→  };
134→}
135→
136→/**
137→ * The prior μ for one author: the leave-one-out mean of the other authors'
138→ * validation rates, itself shrunk toward neutral by how many outcomes those
139→ * authors have. A pool of one other author with one outcome is not a pool
140→ * mean, it is one coin flip; treating it as the truth pulled every author
141→ * toward whichever extreme their single neighbour happened to land on
142→ * (one validation scored below one correction). With no other authors the
143→ * prior is exactly neutral, and the source string says so.
144→ */
145→export function priorFor(tallies, author, alpha = ALPHA) {
146→  const loo = leaveOneOutMean(tallies, author);
147→  let others = 0, outcomes = 0;
148→  for (const [a, t] of tallies) {
149→    const n = t.validated + t.corrected;
150→    if (a !== author && n > 0) { others += 1; outcomes += n; }
151→  }
152→  if (loo === null) {
153→    return { mu: NEUTRAL_PRIOR, prior_source: `neutral ${NEUTRAL_PRIOR}: no other author has cross-person outcomes` };
154→  }
155→  const mu = (outcomes * loo + alpha * NEUTRAL_PRIOR) / (outcomes + alpha);
156→  return {
157→    mu,
158→    prior_source: `leave-one-out mean of ${others} other author(s) over ${outcomes} outcome(s), shrunk toward neutral ${NEUTRAL_PRIOR}`,
159→  };
