162→/** Score every author seen as a producer in the events, by user and by agent. */
163→export function allAuthors(events, opts = {}) {
164→  const out = { user: [], agent: [] };
165→  for (const by of ["user", "agent"]) {
166→    const seen = new Set(events.map((e) => e[KEY[by]]).filter(Boolean));
167→    for (const author of [...seen].sort()) out[by].push(authorConfidence(events, author, { ...opts, by }));
168→  }
169→  return out;
170→}
